//! Temporary ACT compatibility probe; removed after before/after verification.
fn main() {
    let mut bytes = [0u8; 772];
    for (color, index) in bytes[..768].chunks_exact_mut(3).zip(0u8..=255) {
        color.copy_from_slice(&[index, 255 - index, 17]);
    }
    bytes[768..772].copy_from_slice(&[1, 0, 1, 1]);
    let result = photocraft_algo::palettes::parse_act(&bytes);
    println!("{:?}", result.map(|p| (p.colors.len(), p.colors.first().copied(), p.colors.last().copied())));
}
